const {closed,date:closedAt}=Program.snapshot();
const expiryDate=Program.monthAfter(closedAt);
const dateFormat=new Intl.DateTimeFormat('es-GT',{day:'numeric',month:'long',year:'numeric'});
const expiry=dateFormat.format(expiryDate);
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',gift:'<rect x="3" y="9" width="18" height="4" rx="1"/><path d="M5 13v8h14v-8M12 9v12"/><path d="M12 9C4 10 4 2 8 3c3 0 4 6 4 6Zm0 0c8 1 8-7 4-6-3 0-4 6-4 6Z"/>',history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',card:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20M6 15h4"/>',bell:'<path d="M5 16h14l-2-3V9a5 5 0 0 0-10 0v4Zm5 4h4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m6 12 4 4 8-8"/>'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.gift}</svg>`;
const nav=[['inicio','Inicio','home'],['premios','Premios','gift'],['recorrido','Recorrido','history'],['tarjeta','Mi tarjeta','card']];
const prizes=[
 {id:'p3',source:'Procedimiento 3',title:'50% en un medicamento',state:'used',description:'50% en un medicamento de una cuenta. Premio utilizado en una cuenta anterior.'},
 {id:'p6',source:'Procedimiento 6',title:'Suite privada sin costo',state:'available',description:'Una noche en suite privada sin costo de habitación, sujeta a disponibilidad. No incluye servicios médicos ni medicamentos.'},
 {id:'p9',source:'Procedimiento 9',title:'50% en una noche de suite',state:'available',description:'50% en la tarifa de una noche de suite, sujeto a disponibilidad. No incluye servicios médicos ni medicamentos.'},
 {id:'p12',source:'Procedimiento 12',title:'Suite sin costo',state:closed?'available':'locked',description:'Una noche de suite sin costo de habitación, sujeta a disponibilidad. No incluye servicios médicos ni medicamentos.'},
 {id:'silver',source:'Categoría Silver',title:'10% en medicamentos',state:closed?'available':'locked',description:`Descuento en medicamentos de una cuenta. Vigente un mes desde el cierre del ciclo${closed?`, hasta el ${expiry}`:''}.`},
 {id:'gold',source:'Categoría Gold',title:'15% en laboratorio',state:'locked',description:'Descuento en laboratorio de una cuenta. Vigencia de un mes desde el cierre del ciclo Silver.'},
 {id:'platinum',source:'Categoría Platinum',title:'20% en medicina + 5% en cuentas',state:'locked',description:'20% en medicina de una cuenta y 5% en todas las cuentas al alcanzar Platinum.'}
];
const statusText={used:'Usado',available:'Disponible',locked:'Bloqueado'};
const content=document.querySelector('#content'),dialog=document.querySelector('#detail');
const query=`${closed?`?cierre=1&fecha=${closedAt}`:''}`;
const cardUrl=`tarjeta.html${query}`;
const intro=(tag,title,subtitle)=>`<div class="page-intro"><p class="eyebrow">${tag}</p><h1>${title}</h1><p>${subtitle}</p></div>`;
const card=(p)=>`<button class="prize-item ${p.state}" data-prize="${p.id}"><span class="prize-mark">${p.state==='used'?icon('check'):icon('gift')}</span><span class="prize-main"><small>${p.source}</small><strong>${p.title}</strong></span><span class="prize-state">${statusText[p.state]}</span></button>`;
const cycle=()=>`<section class="cycle-card" aria-label="${closed?'Ciclo 2: 0 de 12':'Ciclo 1: 11 de 12'} procedimientos"><div class="cycle-head"><div><p class="eyebrow">TU RECORRIDO · CICLO ${closed?'02':'01'}</p><h2>${closed?'Ciclo Silver en curso.':'Ciclo Bronce en curso.'}</h2><p>${closed?'El ciclo Bronce terminó con 12 procedimientos.':'Un procedimiento más para completar el ciclo Bronce.'}</p></div><div class="counter"><strong>${closed?'0':'11'}</strong><span>/ 12</span></div></div><div class="segments" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i class="${!closed&&i<11?'filled':''}"></i>`).join('')}</div><div class="cycle-bottom"><span>${closed?'Categoría Silver':'Categoría Bronce'}</span><button data-route="recorrido">Ver mi recorrido ${icon('arrow')}</button></div></section>`;
const categories=()=>`<div class="category-grid" aria-label="Todas las categorías">${[
 ['Bronce','Tu punto de partida','Premios por 3, 6, 9 y 12 procedimientos.',closed?'Completada':'Actual','bronze'],
 ['Silver','Completa el ciclo Bronce','10% en medicamentos de una cuenta · un mes.',closed?'Actual':'Por alcanzar','silver'],
 ['Gold','Completa el ciclo Silver','15% en laboratorio de una cuenta · un mes.','Por alcanzar','gold'],
 ['Platinum','Completa el ciclo Gold','20% en medicina de una cuenta + 5% en todas las cuentas.','Por alcanzar','platinum']
 ].map(([name,trigger,detail,state,tone])=>`<article class="category-tile ${tone} ${state==='Actual'?'current':''}"><span class="category-dot"></span><span class="category-status">${state}</span><h3>${name}</h3><strong>${trigger}</strong><p>${detail}</p></article>`).join('')}</div>`;
function render(){let route=location.hash.slice(1)||'inicio';if(!nav.some(x=>x[0]===route))route='inicio';document.querySelectorAll('.desktop-nav,.mobile-nav').forEach(el=>el.innerHTML=nav.map(([id,title,ico])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ico)}<span>${title}</span></a>`).join(''));
 if(route==='inicio')content.innerHTML=`<div class="page-intro greeting"><div><p class="eyebrow">MÉDICOS UTATLÁN</p><h1>Dr. Alejandro Toledo</h1><p>Resumen de procedimientos y premios.</p></div><div class="membership ${closed?'level-silver':'level-bronze'}"><span></span>Nivel ${closed?'Silver':'Bronce'}</div></div>${closed?`<div class="upgrade"><strong>Bronce → Silver</strong><span>Completaste el ciclo y recibiste tu premio de categoría.</span></div>`:''}${cycle()}<div class="dashboard-grid"><section><div class="section-heading"><h2>Tus premios</h2><button class="text-button" data-route="premios">Ver todos</button></div><div class="reward-stack">${prizes.filter(p=>p.state==='available').slice(0,3).map(card).join('')}</div></section><section><div class="section-heading"><h2>Actividad reciente</h2><button class="text-button" data-route="recorrido">Ver recorrido</button></div><div class="mini-card"><div class="activity-row"><span class="status-icon">${icon('check')}</span><span class="body"><strong>${closed?'Procedimiento PR-0048 confirmado':'11 procedimientos confirmados'}</strong><small>${closed?'Cuenta cerrada en Cuentas':'Ciclo Bronce en curso'}</small></span><span class="count">${closed?'+1':'11/12'}</span></div></div><p class="note">Cada procedimiento cuenta una sola vez al terminar en Cuentas.</p></section></div><div class="portal-teaser"><span class="eyebrow">TU CREDENCIAL</span><p>Código de barras para Recepción. QR para abrir tu portal.</p><a href="${cardUrl}">Ver mi tarjeta →</a></div>`;
 if(route==='premios')content.innerHTML=`${intro('MIS PREMIOS','Premios y categorías.',`${prizes.filter(p=>p.state==='available').length} disponibles · ${prizes.filter(p=>p.state==='used').length} usado`)}${categories()}<h2 class="group-title">Premios del ciclo Bronce</h2><div class="prize-list">${prizes.slice(0,4).map(card).join('')}</div><h2 class="group-title">Por categoría</h2><div class="prize-list">${prizes.slice(4).map(card).join('')}</div><p class="note">Cada premio de una cuenta se utiliza una sola vez. Los premios Silver y Gold tienen un mes de vigencia desde el cierre del ciclo que los desbloquea. Los premios disponibles se conservan al iniciar otro ciclo.</p>`;
 if(route==='recorrido')content.innerHTML=`${intro('MI RECORRIDO','Tu trayectoria médica.',closed?'Categoría Silver · ciclo 2':'Categoría Bronce · ciclo 1')}${cycle()}<div class="path-list"><div><span class="path-no">01</span><div><strong>Ciclo Bronce</strong><p>${closed?'Completado: 12/12 procedimientos.':'En curso: 11/12 procedimientos.'}</p></div></div><div><span class="path-no">02</span><div><strong>Ciclo Silver</strong><p>${closed?'Activo: 0/12 procedimientos.':'Se inicia al completar el ciclo Bronce.'}</p></div></div><div><span class="path-no">03</span><div><strong>Gold</strong><p>Se alcanza al completar el ciclo Silver. Desbloquea 15% en laboratorio de una cuenta, vigente un mes.</p></div></div><div><span class="path-no">04</span><div><strong>Platinum</strong><p>20% en medicina de una cuenta y 5% en todas las cuentas.</p></div></div></div>`;
 if(route==='tarjeta')content.innerHTML=`${intro('MI CREDENCIAL','Una tarjeta, dos accesos.','Identificación en Recepción y consulta de tu portal médico.')}<div class="card-preview"><div class="membership-card"><span>SANATORIO PRIVADO UTATLÁN</span><strong>Dr. Alejandro Toledo</strong><small>MÉDICOS UTATLÁN · ${closed?'SILVER':'BRONCE'}</small></div><div><p>El código de barras identifica tu tarjeta para vincularte a un procedimiento privado. El QR abre tu espacio médico.</p><a class="primary-link" href="${cardUrl}">Ver frente y reverso →</a></div></div>`;
 document.querySelector('.header .brand').href=`portal.html${query}#inicio`;
 document.title=`${nav.find(n=>n[0]===route)?.[1]} · Médicos Utatlán`;
}
function showModal(html){document.querySelector('#dialog-body').innerHTML=html;dialog.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.route)location.hash=b.dataset.route;if(b.dataset.prize){const p=prizes.find(x=>x.id===b.dataset.prize);showModal(`<span class="label">${p.source} · ${statusText[p.state]}</span><h2 id="dialog-title">${p.title}</h2><p>${p.description}</p>${p.state==='available'?'<div class="callout">Disponible en tu cuenta para consultar sus condiciones de uso.</div>':''}<button class="primary-button" data-dismiss>Entendido</button>`);}if(b.dataset.modal==='notificaciones')showModal(`<h2 id="dialog-title">Tus novedades</h2><div class="notification-item"><small>TU RECORRIDO</small><p>${closed?'El procedimiento PR-0048 cerró tu ciclo Bronce. Ahora estás en Silver.':'Te falta un procedimiento para completar tu ciclo Bronce.'}</p></div><div class="notification-item"><small>TUS PREMIOS</small><p>${closed?`Tu premio de 10% en medicamentos está disponible hasta el ${expiry}.`:'Consulta los premios de tus procedimientos 6 y 9.'}</p></div>`);if(b.hasAttribute('data-dismiss')||b.id==='close-dialog')dialog.close();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>{render();scrollTo(0,0);content.focus({preventScroll:true});});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));render();

window.addEventListener('storage',e=>{if(e.key===Program.key)location.reload();});
